/bin/bash -lc "python3 -m py_compile jq lexer.py && python3 - <<'PY'
from lexer import Lexer, LexerError
for s in ['.foo + "'$value | [., "text", @json]'"', '\"value=\\\\(.) # trailing comment', '\"u\\\\vw\"']:
    try: print(s, [(t.kind,t.text) for t in Lexer(s).tokenize()])
    except LexerError as e: print(type(e).__name__, e)
PY
python3 -m unittest discover -s tests -v
printf '7\\n' | ./jq -c '\"value=\\\\(.) # trailing comment'; printf 'null\\n' | ./jq -c '\"u\\\\vw\"'; printf 'null\\n' | ./jq -c '.foo + "'$value | [., "text", @json'"'"

